import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceDollAcceptedDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",D=P+"NativeSourceDamageDisplay",N=P+"NativeSourceDollAccepted";
 static void need(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var original=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){original.add(e.getName());var following=jar.getJarEntry(e.getName());need(following!=null,"no deletions");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(following).readAllBytes()))changed.add(e.getName());}need(changed.equals(Set.of(PC+".class",D+".class",D+"$Plan.class")),"exact archive scope");int methods=0,physical=0,doll=0,accepted=0;
  for(var name:List.of(PC,D,D+"$Plan")){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(old.methods.size()==now.methods.size(),"no existing method additions");need(now.fields.size()==old.fields.size()+(name.endsWith("$Plan")?1:0),"one optional pending field");for(int i=0;i<old.fields.size();i++){var x=old.fields.get(i);var y=now.fields.get(i);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields unchanged");}if(name.endsWith("$Plan")){var f=now.fields.get(now.fields.size()-1);need(f.name.equals("nativeSourceDollPending")&&f.desc.equals("Ljava/lang/Object;")&&f.access==ACC_VOLATILE,"volatile detached pending slot");}
   for(var before:old.methods){var after=now.methods.stream().filter(x->x.name.equals(before.name)&&x.desc.equals(before.desc)).findFirst().orElseThrow();for(var node:after.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)){
    if(call.name.equals("physical")){need(name.equals(PC)&&before.name.equals("nativeSourceControlledOriginal_attack"),"physical root only");var proc=FreezeAcceptedMethods.prev(call);need(proc instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==171,"original rolled proc local");after.instructions.remove(proc);call.owner=D;call.desc=call.desc.replace("L"+P+"NativeMagicDollEffects$AttackProc;)",")");physical++;}
    else if(call.name.equals("submitted")){need(name.equals(PC)&&before.name.equals("nativeSourceControlledOriginal_attack"),"only old post-submission bridges");call.owner=P+"NativeSourceKiringkuAdmission";call.name="doll";doll++;}
    else if(call.name.equals("completed")){need(name.equals(D)&&before.name.equals("accepted"),"existing accepted completion only");var load=FreezeAcceptedMethods.prev(call);need(load instanceof VarInsnNode v&&v.var==0,"actual accepted frame");after.instructions.remove(load);after.instructions.remove(call);accepted++;}else throw new AssertionError(call.name);
   }need(Arrays.equals(FreezeSourceTargetDelta.body(old,before,before.name,before.access),FreezeSourceTargetDelta.body(now,after,before.name,before.access)),"original inverse "+name+'.'+before.name);methods++;}
  }need(physical==1&&doll==3&&accepted==1,"exact bounded ports");int fresh=0;
  for(var e:Collections.list(jar.entries()))if(!original.contains(e.getName())){need(Set.of(N+".class",N+"$Pending.class").contains(e.getName()),"only detached helper/pending");fresh++;var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));for(var f:c.fields){need((f.access&ACC_STATIC)==0||f.value instanceof String,"no global registry");need(!f.desc.contains("Context")&&!f.desc.contains("Receipt")&&!f.desc.contains("Scope")&&!f.desc.contains("Frame")&&!f.desc.contains("Plan"),"no captured continuation graph");}for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor"),"no new worker/TLS");if(n instanceof MethodInsnNode call){need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("Repository")&&!call.owner.contains("GameStateStore"),"no persistence authority");need(!(call.owner.equals(P+"NativeMagicDollEffects")&&(call.name.equals("attack")||call.name.equals("defense"))),"no rerolled proc RNG");}}}
  need(fresh==2,"two new classes");System.out.println("PASS independent accepted-doll inverse: "+methods+" original methods, actual rolled proc preserved, detached existing accepted completion, no new worker/TLS/persistence");
 }}
}
